 &TrnMode = TrnMode.Delete msg('GXM_confdelete') EndIf EndIf &DDO_TitleSettingsIcons = GetWWPTitleSettingsIcons() Do 'LoadComboSHYMA_OPS_PlantaId' Do 'LoadComboSHYMA_OPS_SectorId' Do 'LoadComboSHYMA_OPS_SHYMA_OPSEmpresaContratistaId' Do 'LoadComboSHYMA_OPSObservadores' Do 'LoadComboSHYMA_OPSGestionRiesgo' Do 'LoadComboSHYMA_OPSProtocolosMortales' Do 'LoadComboSHYMA_OPSClasificacionObservacion' Do 'LoadComboSHYMA_OPSRelacionObservacion' SHYMA_OPS_SHYMA_OPSId.Visible = False &fPlantaId.Visible = False &fSectorId.Visible = False
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
If &TrnMode = TrnMode.Insert &Aplica = True Else If &SHYMA_OPS.SHYMA_OPSDescripcionAC = !"N/A" &Aplica = False Else &Aplica = True
EndIf EndIf If &Aplica SHYMA_OPS_SHYMA_OPSDescripcionAC.Visible = True Else SHYMA_OPS_SHYMA_OPSDescripcionAC.Visible = False EndIf
If &TrnMode = TrnMode.Update or &TrnMode = TrnMode.Display &AccionCorrectiva = &SHYMA_OPS.SHYMA_OPSDescripcionAC EndIf &FechaMin = &Today - 7
EndEvent
