Sub 'CheckRequiredFields'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&CheckRequiredFieldsResult = True If &SHYMA_OPS.SHYMA_OPSFecha.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Fecha'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSFecha.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSTarea.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Tarea'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSTarea.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.PlantaId.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Planta'), DVMessageType.error, Combo_SHYMA_OPS_PlantaId.DDOInternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SectorId.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Sector'), DVMessageType.error, Combo_SHYMA_OPS_SectorId.DDOInternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSLugar.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Lugar'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSLugar.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPSObservadores.Count = 0 Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Observadores - Nombre y Apellido'), DVMessageType.error, Combo_SHYMA_OPSObservadores.DDOInternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSAPRRevisados.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute',' Documentos o APR revisados. (En caso de ser un documento, aclare el código)'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSAPRRevisados.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPSGestionRiesgo.Count = 0 Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Método de gestión de riesgo'), DVMessageType.error, Combo_SHYMA_OPSGestionRiesgo.DDOInternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPSProtocolosMortales.Count = 0 Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Protocolos mortales o catastróficos considerados'), DVMessageType.error, Combo_SHYMA_OPSProtocolosMortales.DDOInternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSControlesCriticos.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Controles críticos verificados:'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSControlesCriticos.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSTareaRealizada.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','¿La tarea se realizó de acuerdo al Documento o APR?'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSTareaRealizada.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSRequiereRevisionATR.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','¿Se requiere revisión del documento o APR?'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSRequiereRevisionATR.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSRiesgoTRC.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','¿Se tuvieron en cuenta situaciones de riesgos de TRC?'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSRiesgoTRC.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSRiesgoControlado.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','¿Fueron controlados los riesgos de golpes con/contra objetos?'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSRiesgoControlado.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSMedidasRiesgoManos.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','¿Se tomaron medidas ante riesgos de lesión en manos?'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSMedidasRiesgoManos.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSMedidasRiesgoLesiones.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','¿Se tomaron medidas para evitar lesiones ergonómicas?'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSMedidasRiesgoLesiones.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSRevisionHerramientas.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute',' ¿Se revisaron las herramientas/equipos/EPP antes de iniciar la tarea?'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSRevisionHerramientas.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSRevisionEquiposMoviles.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','¿Se revisaron las máquinas y equipos móviles antes de iniciar la tarea?'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSRevisionEquiposMoviles.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSEnergiaRevisada.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','¿Todas las energías fueron: identificadas, aisladas, bloqueadas, etiquetadas, disipadas'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSEnergiaRevisada.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSEscaleraRevisada.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','¿Las escaleras y andamios fueron revisados y aprobados antes del inicio de la tarea?'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSEscaleraRevisada.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSEquipoElectricoDisyuntor.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','¿Los equipos eléctricos empleados disponen de disyuntor y llave térmica?'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSEquipoElectricoDisyuntor.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPSClasificacionObservacion.Count = 0 Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Clasificación de la observación:'), DVMessageType.error, Combo_SHYMA_OPSClasificacionObservacion.DDOInternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSResumenObservacion.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Resumen de lo observado'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSResumenObservacion.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPSRelacionObservacion.Count = 0 Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Lo observado está relacionado con:'), DVMessageType.error, Combo_SHYMA_OPSRelacionObservacion.DDOInternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf If &SHYMA_OPS.SHYMA_OPSDetalleAI.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Detalle las acciones inmediatas'), DVMessageType.error, SHYMA_OPS_SHYMA_OPSDetalleAI.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
If &SHYMA_OPSObservadores.Count > 10 Msg("El límite máximo de observadores es 10") &CheckRequiredFieldsResult = False EndIf
If &SHYMA_OPS.SHYMA_OPSDescripcionAC.IsEmpty() Msg('Detalle las acciones correctivas.') &CheckRequiredFieldsResult = False EndIf
If not &SHYMA_OPS.SHYMA_OPSFecha.IsEmpty() and (&SHYMA_OPS.SHYMA_OPSFecha < &FechaMin or &SHYMA_OPS.SHYMA_OPSFecha > ( &Today + 1)) Msg('Fecha inválida. Solo puede seleccionar hasta siete días hacia atrás desde la fecha actual.') &CheckRequiredFieldsResult = False EndIf
// msg('&SHYMA_OPS.SHYMA_OPSDescripcionAC: ' + &SHYMA_OPS.SHYMA_OPSDescripcionAC.Trim())
EndSub
